25	const key = id.trim().toUpperCase();
26	const incident = load().find((x) => x.id === key);
27	if (!incident) {
28	  console.error(`fetch-incident: no incident ${key} in the ops queue`);
29	  process.exit(1);
30	}
31	
32	if (asJson) {
33	  console.log(JSON.stringify(incident, null, 2));
34	} else {
35	  const wrap = (text, width = 88) => {
36	    const out = [];
37	    let line = "";
38	    for (const word of text.split(/\s+/)) {
39	      if (line && line.length + word.length + 1 > width) {
40	        out.push(line);
41	        line = word;
42	      } else {
43	        line = line ? `${line} ${word}` : word;
44	      }
45	    }
46	    if (line) out.push(line);
47	    return out;
48	  };
49	  const out = [
50	    `${incident.id}  ${incident.title}`,
51	    `status: ${incident.status}   priority: ${incident.priority}   area: ${incident.area}   reported: ${incident.reported} by ${incident.reporter}`,
52	    "",
53	    ...wrap(incident.description),
54	    "",
55	    "Acceptance:",
56	    ...wrap(incident.acceptance).map((l) => `  ${l}`),
57	    "",
58	    "Files:",
59	    ...incident.files.map((f) => `  ${f}`),
60	  ];
61	  console.log(out.join("\n"));
62	}
